mapper.select:
/* com.portal.board.com.TemplateManageMapper.selectTemplateInfs */ SELECT a.TMPLAT_ID, a.TMPLAT_NM, a.TMPLAT_SE_CODE, a.TMPLAT_COURS, a.USE_AT, a.FRST_REGISTER_ID, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM, b.USER_NM AS FRST_REGISTER_NM, c.CODE_NM AS TMPLAT_SE_CODE_NM FROM LETTNTMPLATINFO a LEFT OUTER JOIN COMVNUSERMASTER b ON a.FRST_REGISTER_ID = b.ESNTL_ID LEFT OUTER JOIN LETTCCMMNDETAILCODE c ON a.TMPLAT_SE_CODE = c.CODE AND c.CODE_ID = 'COM005' WHERE 1 = 1
AND a.TMPLAT_SE_CODE = #{tmplatSeCode}
AND a.TMPLAT_NM LIKE CONCAT('%', #{searchWrd}, '%')
AND c.CODE_NM LIKE CONCAT('%', #{searchWrd}, '%')
ORDER BY a.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.board.com.TemplateManageMapper.selectTemplateInfsCnt */ SELECT COUNT(a.TMPLAT_ID) FROM LETTNTMPLATINFO a LEFT OUTER JOIN COMVNUSERMASTER b ON a.FRST_REGISTER_ID = b.ESNTL_ID LEFT OUTER JOIN LETTCCMMNDETAILCODE c ON a.TMPLAT_SE_CODE = c.CODE AND c.CODE_ID = 'COM005' WHERE 1 = 1
AND a.TMPLAT_SE_CODE = #{tmplatSeCode}
AND a.TMPLAT_NM LIKE CONCAT('%', #{searchWrd}, '%')
AND c.CODE_NM LIKE CONCAT('%', #{searchWrd}, '%')

mapper.update:
/* com.portal.board.com.TemplateManageMapper.deleteTemplateInf */
UPDATE LETTNTMPLATINFO
   SET USE_AT          = 'N',
       LAST_UPDUSR_ID  = #{lastUpdusrId},
       LAST_UPDT_PNTTM = SYSDATE()
 WHERE TMPLAT_ID = #{tmplatId}
